def _call_backend_criticalpoints(node_type, data):

    numpy_array = paraview_vti_to_numpy(data)
    cps = critical_points(numpy_array)
    numPoints = cps.shape[0]

    points = vtk.vtkPoints()
    points.SetNumberOfPoints(numPoints)

    for i in range(numPoints):
        points.SetPoint(i, cps[i,1], cps[i,2], 0.0)

    ugrid = vtk.vtkUnstructuredGrid()
    ugrid.SetPoints(points)

    ugrid.Allocate(numPoints)
    for i in range(numPoints):
        ugrid.InsertNextCell(vtk.VTK_VERTEX, 1, [i])

    arr = vtk.vtkFloatArray()
    arr.SetName("CriticalType")
    arr.SetNumberOfTuples(cps.shape[0])
    for i in range(numPoints):
        arr.SetValue(i, cps[i,0])

    ugrid.GetPointData().AddArray(arr)

    prod = servermanager.sources.TrivialProducer()
    prod.GetClientSideObject().SetOutput(ugrid)
    prod.UpdatePipeline()

    return node_type(prod)

